<script>(()=>{const show=n=>{document.querySelectorAll('[data-panel]').forEach(x=>x.classList.toggle('active',x.dataset.panel===String(n)));document.querySelectorAll('[data-step]').forEach(x=>x.classList.toggle('active',x.dataset.step===String(n)));};document.querySelectorAll('[data-step],[data-next]').forEach(x=>x.addEventListener('click',()=>show(x.dataset.step||x.dataset.next)));const roles=document.getElementById('role-select'),primary=document.getElementById('primary-role'),portal=document.getElementById('portal-access'),stdScopes=document.getElementById('standard-scopes'),customer=document.getElementById('customer-select'),sites=document.getElementById('site-select');const portalRoles=['CUSTOMER'];const filterSites=()=>{if(!sites||!customer)return;const cid=customer.value;[...sites.options].forEach(o=>{const visible=!!cid&&o.dataset.customer===cid;o.hidden=!visible;if(!visible)o.selected=false;});};const sync=()=>{const selected=[...roles.selectedOptions].map(x=>x.value);[...primary.options].forEach(x=>x.hidden=!selected.includes(x.value));if(!selected.includes(primary.value))primary.value=selected[0]||'';const isPortal=selected.some(x=>portalRoles.includes(x));portal?.classList.toggle('active',isPortal);if(stdScopes)stdScopes.style.display=isPortal?'none':'grid';if(customer)customer.required=isPortal;if(isPortal)filterSites();};roles?.addEventListener('change',sync);customer?.addEventListener('change',filterSites);sync();filterSites();})();</script>
